/* MISRA C:2004 Rule 14.7 and C:2012/2023 Rule 15.5 deviation: early
   returns keep validation failures next to their bounds/resource checks.
   C:2012/2023 Rule 17.7 deviation: synchronization cleanup and calls whose
   arguments are validated constants may discard status; initialized ThreadX
   objects and application-thread context are public API preconditions. */

/* Original implementation from OASIS MQTT 5.0, sections 1.5, 2.2 and 3.
   No external codec or allocation is needed; chained packets are read directly. */
#define NXD_MQTT_CLIENT_SOURCE_CODE
#include "nxd_mqtt_client.h"

/* A bounded cursor over either an application buffer or a packet chain. */
typedef struct MQTT5_READER_STRUCT
{
    NX_PACKET *packet;
    const UCHAR *data;
    ULONG offset;
    ULONG end;
} MQTT5_READER;

/* Read an unsigned network-order integer without unaligned accesses. */
static UINT mqtt5_number(MQTT5_READER *reader, UINT count, ULONG *value)
{
UCHAR bytes[4];
ULONG copied;
UINT i;

    if (count > sizeof(bytes) || reader -> offset > reader -> end ||
        count > reader -> end - reader -> offset)
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    if (reader -> packet != NX_NULL)
    {
        if (nx_packet_data_extract_offset(reader -> packet, reader -> offset, bytes, count, &copied) || copied != count)
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
    }
    else
    {
        for (i = 0; i < count; i++)
        {
            bytes[i] = reader -> data[reader -> offset + i];
        }
    }
    reader -> offset += count;
    *value = 0;
    for (i = 0; i < count; i++)
    {
        *value = (*value << 8) | bytes[i];
    }
    return(NX_SUCCESS);
}

/* Decode a canonical MQTT variable-byte integer (at most four bytes). */
static UINT mqtt5_vbi(MQTT5_READER *reader, ULONG *value)
{
ULONG byte;
ULONG multiplier = 1;
UINT i;

    *value = 0;
    for (i = 0; i < 4; i++)
    {
        if (mqtt5_number(reader, 1, &byte))
        {
            return(NXD_MQTT_PARTIAL_PACKET);
        }
        *value += (byte & 127u) * multiplier;
        if ((byte & 128u) == 0)
        {
            return((i && byte == 0) ? NXD_MQTT_INVALID_PACKET : NX_SUCCESS);
        }
        multiplier *= 128u;
    }
    return(NXD_MQTT_INVALID_PACKET);
}

/* Encode a variable-byte integer into the caller's four-byte buffer. */
UINT _nxd_mqtt5_vbi_encode(ULONG value, UCHAR *bytes)
{
UINT length = 0;

    do
    {
        bytes[length] = (UCHAR)(value % 128u);
        value /= 128u;
        if (value)
        {
            bytes[length] |= 128u;
        }
        length++;
    } while (value && length < 4);
    return(length);
}

/* Validate UTF-8 strings, or skip a length-prefixed binary value. */
static UINT mqtt5_string(MQTT5_READER *reader, UINT binary)
{
ULONG length;
ULONG end;
ULONG byte;
ULONG codepoint;
ULONG minimum;
UINT extra;
UINT i;

    if (mqtt5_number(reader, 2, &length) || length > reader -> end - reader -> offset)
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    end = reader -> offset + length;
    if (binary)
    {
        reader -> offset = end;
        return(NX_SUCCESS);
    }
    while (reader -> offset < end)
    {
        if (mqtt5_number(reader, 1, &byte))
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
        if (byte < 128u)
        {
            if (byte == 0)
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
            continue;
        }
        if (byte >= 0xC2u && byte <= 0xDFu)
        {
            extra = 1;
            codepoint = byte & 31u;
            minimum = 128u;
        }
        else if (byte >= 0xE0u && byte <= 0xEFu)
        {
            extra = 2;
            codepoint = byte & 15u;
            minimum = 2048u;
        }
        else if (byte >= 0xF0u && byte <= 0xF4u)
        {
            extra = 3;
            codepoint = byte & 7u;
            minimum = 65536u;
        }
        else
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
        if (extra > end - reader -> offset)
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
        for (i = 0; i < extra; i++)
        {
            if (mqtt5_number(reader, 1, &byte) || (byte & 0xC0u) != 0x80u)
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
            codepoint = (codepoint << 6) | (byte & 63u);
        }
        if (codepoint < minimum || codepoint > 0x10FFFFUL ||
            (codepoint >= 0xD800u && codepoint <= 0xDFFFu))
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
    }
    return(NX_SUCCESS);
}

/* Validate property legality, multiplicity and encoding for server packets.
   Topic aliases and subscription identifiers are not requested by this client. */
static UINT mqtt5_properties(MQTT5_READER *reader, UINT type, NXD_MQTT_CLIENT *client)
{
ULONG id;
ULONG value;
ULONG seen[2] = {0, 0};
ULONG mask;
UINT format;
UINT allowed;
UINT status;

    while (reader -> offset < reader -> end)
    {
        if (mqtt5_vbi(reader, &id) || id > 42u)
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
        allowed = 0;
        format = 0;
        switch (id)
        {
        case 1: format = 1;
        allowed = (type == 3);
        break;
        case 2: format = 4;
        allowed = (type == 3);
        break;
        case 3: case 8: format = 5;
        allowed = (type == 3);
        break;
        case 9: format = 6;
        allowed = (type == 3);
        break;
        case 17: format = 4;
        allowed = (type == 2 || type == 14);
        break;
        case 18: case 26: format = 5;
        allowed = (type == 2);
        break;
        case 19: case 33: case 34: format = 2;
        allowed = (type == 2);
        break;
        case 28: format = 5;
        allowed = (type == 2 || type == 14);
        break;
        case 31: format = 5;
        allowed = (type == 2 || type == 4 || type == 9 || type == 11 || type == 14);
        break;
        case 36: case 37: case 40: case 41: case 42:
            format = 1;
            allowed = (type == 2);
            break;
        case 38: format = 7;
        allowed = 1;
        break;
        case 39: format = 4;
        allowed = (type == 2);
        break;
        default: return(NXD_MQTT_INVALID_PACKET);
        }
        if (!allowed)
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
        mask = 1UL << (id % 32u);
        if (id != 38u && (seen[id / 32u] & mask))
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
        seen[id / 32u] |= mask;
        value = 0;
        if (format <= 4)
        {
            status = mqtt5_number(reader, format, &value);
            if ((format == 1 && value > 1u) || ((id == 33u || id == 39u) && value == 0))
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
        }
        else
        {
            MQTT5_READER topic = *reader;
            status = mqtt5_string(reader, format == 6);
            if (!status && id == 8u)
            {
                ULONG topic_length;
                ULONG byte;
                if (mqtt5_number(&topic, 2, &topic_length) || !topic_length)
                {
                    return(NXD_MQTT_INVALID_PACKET);
                }
                while (topic.offset < reader -> offset)
                {
                    if (mqtt5_number(&topic, 1, &byte) || byte == '+' || byte == '#')
                    {
                        return(NXD_MQTT_INVALID_PACKET);
                    }
                }
            }
            if (!status && format == 7)
            {
                status = mqtt5_string(reader, 0);
            }
        }
        if (status)
        {
            return(status);
        }
        if (client != NX_NULL && type == 2)
        {
            switch (id)
            {
            case 19: client -> nxd_mqtt_keepalive = (UINT)value * NX_IP_PERIODIC_RATE;
            break;
            case 33: client -> nxd_mqtt_peer_receive_maximum = (UINT)value;
            break;
            case 36: client -> nxd_mqtt_peer_maximum_qos = (UINT)value;
            break;
            case 37: client -> nxd_mqtt_peer_retain_available = (UINT)value;
            break;
            case 39: client -> nxd_mqtt_peer_maximum_packet_size = value;
            break;
            case 40: client -> nxd_mqtt_peer_wildcard_available = (UINT)value;
            break;
            default: break;
            }
        }
    }
    return(NX_SUCCESS);
}

/* Validate outgoing PUBLISH properties without copying or allocating storage. */
UINT _nxd_mqtt5_properties_validate(const UCHAR *data, UINT length, UINT packet_type)
{
MQTT5_READER reader;

    if (data == NX_NULL && length)
    {
        return(NXD_MQTT_INVALID_PARAMETER);
    }
    reader.packet = NX_NULL;
    reader.data = data;
    reader.offset = 0;
    reader.end = length;
    return(mqtt5_properties(&reader, packet_type, NX_NULL));
}

/* Read the length-prefixed property section of one complete MQTT packet. */
UINT _nxd_mqtt5_properties_read(NXD_MQTT_CLIENT *client, NX_PACKET *packet, ULONG *offset,
                               ULONG end, UINT type, ULONG *properties_offset, UINT *properties_length)
{
MQTT5_READER reader;
ULONG length;
UINT status;

    reader.packet = packet;
    reader.data = NX_NULL;
    reader.offset = *offset;
    reader.end = end;
    if (mqtt5_vbi(&reader, &length) || length > end - reader.offset)
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    *properties_offset = reader.offset;
    *properties_length = (UINT)length;
    reader.end = reader.offset + length;
    status = mqtt5_properties(&reader, type, client);
    *offset = reader.end;
    return(status);
}

/* Convert the old PUBLISH payload offset into the MQTT 5 payload offset. */
UINT _nxd_mqtt5_publish_offsets(NX_PACKET *packet, ULONG *offset, ULONG *length,
                               ULONG *properties_offset, UINT *properties_length)
{
ULONG end = *length;
UINT status;

    status = _nxd_mqtt5_properties_read(NX_NULL, packet, offset, end, 3, properties_offset, properties_length);
    if (!status)
    {
        *length = end - *offset;
    }
    return(status);
}

/* Parse CONNACK including the negotiated server limits. */
UINT _nxd_mqtt5_connack(NXD_MQTT_CLIENT *client, NX_PACKET *packet)
{
MQTT5_READER reader;
UINT remaining;
ULONG flags;
ULONG reason;
ULONG property_offset;
UINT property_length;

    if (_nxd_mqtt_read_remaining_length(packet, &remaining, &reader.offset))
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    reader.packet = packet;
    reader.data = NX_NULL;
    reader.end = reader.offset + remaining;
    if (mqtt5_number(&reader, 1, &flags) || mqtt5_number(&reader, 1, &reason) ||
        flags > 1u || (flags && (client -> nxd_mqtt_clean_session || reason)) ||
        !(reason == 0u || (reason >= 0x80u && reason <= 0x8Au) || reason == 0x8Cu || reason == 0x90u ||
          reason == 0x95u || reason == 0x97u || reason == 0x99u || reason == 0x9Au || reason == 0x9Bu ||
          reason == 0x9Cu || reason == 0x9Du || reason == 0x9Fu) ||
        _nxd_mqtt5_properties_read(client, packet, &reader.offset, reader.end, 2, &property_offset, &property_length) ||
        reader.offset != reader.end)
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    client -> nxd_mqtt_session_present = (UINT)flags;
    client -> nxd_mqtt_last_reason_code = (UINT)reason;
    return(reason ? NXD_MQTT5_REASON_ERROR + (UINT)reason : NX_SUCCESS);
}

/* Decode PUBACK, SUBACK and UNSUBACK; this client sends one filter per request. */
UINT _nxd_mqtt5_ack(NXD_MQTT_CLIENT *client, NX_PACKET *packet, USHORT *id, UINT *reason)
{
MQTT5_READER reader;
UINT remaining;
UINT type = packet -> nx_packet_prepend_ptr[0] >> 4;
ULONG value;
ULONG property_offset;
UINT property_length;

    if (_nxd_mqtt_read_remaining_length(packet, &remaining, &reader.offset))
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    reader.packet = packet;
    reader.data = NX_NULL;
    reader.end = reader.offset + remaining;
    if (mqtt5_number(&reader, 2, &value) || value == 0)
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    *id = (USHORT)value; *reason = 0;
    if (type == 4)
    {
        if (remaining > 2)
        {
            if (mqtt5_number(&reader, 1, &value))
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
            *reason = (UINT)value;
        }
        if (remaining > 3 && _nxd_mqtt5_properties_read(NX_NULL, packet, &reader.offset, reader.end, type, &property_offset, &property_length))
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
    }
    else if (type == 9 || type == 11)
    {
        if (_nxd_mqtt5_properties_read(NX_NULL, packet, &reader.offset, reader.end, type, &property_offset, &property_length) ||
            mqtt5_number(&reader, 1, &value))
        {
            return(NXD_MQTT_INVALID_PACKET);
        }
        *reason = (UINT)value;
    }
    else
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    if (type == 4u && !(*reason == 0u || *reason == 0x10u || *reason == 0x80u || *reason == 0x83u ||
        *reason == 0x87u || *reason == 0x90u || *reason == 0x91u || *reason == 0x97u || *reason == 0x99u))
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    if (type == 9u && !(*reason <= 1u || *reason == 0x80u || *reason == 0x83u || *reason == 0x87u ||
        *reason == 0x8Fu || *reason == 0x91u || *reason == 0x97u || *reason == 0x9Eu || *reason == 0xA1u || *reason == 0xA2u))
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    if (type == 11u && !(*reason == 0u || *reason == 0x11u || *reason == 0x80u || *reason == 0x83u ||
        *reason == 0x87u || *reason == 0x8Fu || *reason == 0x91u))
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    client -> nxd_mqtt_last_reason_code = *reason;
    return(reader.offset == reader.end ? NX_SUCCESS : NXD_MQTT_INVALID_PACKET);
}

/* Emit CONNECT properties. Topic Alias Maximum defaults to zero. */
UINT _nxd_mqtt5_connect_properties(NXD_MQTT_CLIENT *client, NX_PACKET *packet, ULONG wait_option)
{
UCHAR bytes[11];
UINT i;

    bytes[0] = 10;
    bytes[1] = 17;
    bytes[6] = 39;
    for (i = 0; i < 4; i++)
    {
        bytes[2 + i] = (UCHAR)(client -> nxd_mqtt_session_expiry >> (24u - 8u * i));
        bytes[7 + i] = (UCHAR)(client -> nxd_mqtt_maximum_packet_size >> (24u - 8u * i));
    }
    return(nx_packet_data_append(packet, bytes, sizeof(bytes), client -> nxd_mqtt_client_packet_pool_ptr, wait_option));
}

/* Change version only when idle, without outstanding packets from another version. */
UINT nxd_mqtt_client_protocol_version_set(NXD_MQTT_CLIENT *client, UINT version)
{
UINT status = NX_SUCCESS;

    if (client == NX_NULL || (version != NXD_MQTT_VERSION_3_1_1 && version != NXD_MQTT_VERSION_5))
    {
        return(NXD_MQTT_INVALID_PARAMETER);
    }
    tx_mutex_get(client -> nxd_mqtt_client_mutex_ptr, TX_WAIT_FOREVER);
    if (client -> nxd_mqtt_client_state != NXD_MQTT_CLIENT_STATE_IDLE ||
        client -> message_transmit_queue_head != NX_NULL || client -> message_receive_queue_head != NX_NULL)
    {
        status = NXD_MQTT_ALREADY_CONNECTED;
    }
    else
    {
        client -> nxd_mqtt_protocol_version = version;
    }
    tx_mutex_put(client -> nxd_mqtt_client_mutex_ptr);
    return(status);
}

/* Configure session expiry in seconds and a receive packet-size budget in bytes. */
UINT nxd_mqtt_client_session_configure(NXD_MQTT_CLIENT *client, ULONG expiry, ULONG maximum_packet_size)
{
UINT status = NX_SUCCESS;

    if (client == NX_NULL || maximum_packet_size < 5 || maximum_packet_size > 268435455UL)
    {
        return(NXD_MQTT_INVALID_PARAMETER);
    }
    tx_mutex_get(client -> nxd_mqtt_client_mutex_ptr, TX_WAIT_FOREVER);
    if (client -> nxd_mqtt_client_state != NXD_MQTT_CLIENT_STATE_IDLE || client -> nxd_mqtt_protocol_version != NXD_MQTT_VERSION_5)
    {
        status = NXD_MQTT_INVALID_PARAMETER;
    }
    else
    {
        client -> nxd_mqtt_session_expiry = expiry;
        client -> nxd_mqtt_maximum_packet_size = maximum_packet_size;
    }
    tx_mutex_put(client -> nxd_mqtt_client_mutex_ptr);
    return(status);
}

/* Explicitly discard a queued message that exceeds the application's capacity. */
UINT nxd_mqtt_client_message_discard(NXD_MQTT_CLIENT *client)
{
NX_PACKET *packet;

    if (client == NX_NULL)
    {
        return(NXD_MQTT_INVALID_PARAMETER);
    }
    tx_mutex_get(client -> nxd_mqtt_client_mutex_ptr, TX_WAIT_FOREVER);
    packet = client -> message_receive_queue_head;
    if (packet != NX_NULL)
    {
        client -> message_receive_queue_head = packet -> nx_packet_queue_next;
        if (client -> message_receive_queue_head == NX_NULL)
        {
            client -> message_receive_queue_tail = NX_NULL;
        }
        client -> message_receive_queue_depth--;
        nx_packet_release(packet);
    }
    tx_mutex_put(client -> nxd_mqtt_client_mutex_ptr);
    return(packet == NX_NULL ? NXD_MQTT_NO_MESSAGE : NX_SUCCESS);
}

/* Validate packet size as soon as the header is available, before buffering a
   large body. Multiple MQTT packets in one TCP receive are counted separately. */
UINT _nxd_mqtt5_packet_check(NXD_MQTT_CLIENT *client, NX_PACKET *packet)
{
MQTT5_READER reader;
ULONG header;
ULONG length;
UINT type;
UINT status;
    reader.packet = packet;
    reader.data = NX_NULL;
    reader.offset = 0;
    reader.end = packet -> nx_packet_length;
    if (mqtt5_number(&reader, 1, &header))
    {
        return(NXD_MQTT_PARTIAL_PACKET);
    }
    type = (UINT)(header >> 4);
    if (!(type == 2u || type == 3u || type == 4u || type == 9u || type == 11u || type == 13u || type == 14u) ||
        (type != 3u && (header & 15u)) || (type == 3u && ((header & 6u) > 2u || ((header & 6u) == 0 && (header & 8u)))))
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    status = mqtt5_vbi(&reader, &length);
    if (status)
    {
        return(status);
    }
    if (reader.offset + length > client -> nxd_mqtt_maximum_packet_size || (type == 13u && length != 0))
    {
        return(NXD_MQTT_INVALID_PACKET);
    }
    if (reader.offset + length <= packet -> nx_packet_length)
    {
        ULONG value;
        ULONG property_offset;
        UINT property_length;
        reader.end = reader.offset + length;
        if (type == 3u)
        {
            ULONG topic_at = reader.offset;
            ULONG topic_length;
            ULONG byte;
            if (mqtt5_string(&reader, 0))
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
            topic_length = reader.offset - topic_at - 2u;
            if (topic_length == 0)
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
            /* Reject MQTT wildcards in a concrete topic. */
            {
                MQTT5_READER topic_reader = reader;
                topic_reader.offset = topic_at + 2u;
                while (topic_reader.offset < reader.offset)
                {
                    if (mqtt5_number(&topic_reader, 1, &byte) || byte == '+' || byte == '#')
                    {
                        return(NXD_MQTT_INVALID_PACKET);
                    }
                }
            }
            if ((header & 6u) && (mqtt5_number(&reader, 2, &value) || value == 0))
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
        }
        if (type == 14u && length)
        {
            if (mqtt5_number(&reader, 1, &value))
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
            client -> nxd_mqtt_last_reason_code = (UINT)value;
            if (length > 1 && _nxd_mqtt5_properties_read(NX_NULL, packet, &reader.offset, reader.end, 14,
                                                       &property_offset, &property_length))
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
            if (reader.offset != reader.end)
            {
                return(NXD_MQTT_INVALID_PACKET);
            }
        }
    }
    return(NX_SUCCESS);
}

/* Validate outgoing topic/filter syntax without an additional large buffer. */
UINT _nxd_mqtt5_topic_validate(const CHAR *topic, UINT length, UINT filter)
{
UINT i;
UCHAR c;
    if (topic == NX_NULL || !length || length > 65535u)
    {
        return(NXD_MQTT_INVALID_PARAMETER);
    }
    for (i = 0; i < length; i++)
    {
        c = (UCHAR)topic[i];
        if (c == 0)
        {
            return(NXD_MQTT_INVALID_PARAMETER);
        }
        if (c == '+' || c == '#')
        {
            if (!filter || (i != 0 && topic[i - 1] != '/') ||
                (c == '#' && i != length - 1u) || (c == '+' && i + 1u < length && topic[i + 1u] != '/'))
            {
                return(NXD_MQTT_INVALID_PARAMETER);
            }
        }
        if (c >= 128u)
        {
            UINT count;
            UINT j;
            UCHAR bytes[6];
            MQTT5_READER reader;
            if (c >= 0xC2u && c <= 0xDFu)
            {
                count = 2;
            }
            else if (c >= 0xE0u && c <= 0xEFu)
            {
                count = 3;
            }
            else if (c >= 0xF0u && c <= 0xF4u)
            {
                count = 4;
            }
            else
            {
                return(NXD_MQTT_INVALID_PARAMETER);
            }
            if (count > length - i)
            {
                return(NXD_MQTT_INVALID_PARAMETER);
            }
            bytes[0] = 0;
            bytes[1] = (UCHAR)count;
            for (j = 0; j < count; j++)
            {
                bytes[2 + j] = (UCHAR)topic[i + j];
            }
            reader.packet = NX_NULL;
            reader.data = bytes;
            reader.offset = 0;
            reader.end = count + 2u;
            if (mqtt5_string(&reader, 0))
            {
                return(NXD_MQTT_INVALID_PARAMETER);
            }
            i += count - 1u;
        }
    }
    return(NX_SUCCESS);
}
